# Shared typography declarations are still scoped independently for every contract.
for folder,cid in folders.items():
 d=C/'elements'/folder;contract=ids[cid]; roots=contract['roots'];selector=':is('+','.join('.'+r+'[data-el="confluence-'+folder+'"]' for r in roots)+')'
 base='''&{box-sizing:border-box;min-width:0;min-height:0;font-family:var(--font-body);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--ink);container-type:inline-size}& *{box-sizing:border-box;min-width:0}& p,& h2,& blockquote{margin:0}& .name{font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);font-size:var(--type-22)}& .fig{font-family:var(--font-display);font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track);font-variant-numeric:tabular-nums}& small{font-size:var(--type-18);font-weight:var(--label-weight);margin-left:calc(var(--gap-sm)/2)}& .note{font-size:var(--type-16);color:var(--n-7);line-height:var(--body-line);font-weight:var(--body-weight);letter-spacing:var(--body-track)}& .kick{font-size:var(--type-12);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track-latin)}& .icon{display:inline-flex;width:32px;height:32px;align-items:center;justify-content:center;flex:none}'''
 responsive='''@container (max-width:650px){& .name{font-size:var(--type-18)}& .fig{font-size:var(--type-40)}& .note{font-size:var(--type-14)}& h2{font-size:var(--type-36)}& .mark{width:40px;height:40px}& .mark .icon{width:22px;height:22px}}@container (max-width:380px){& .name{font-size:var(--type-16)}& .fig{font-size:var(--type-32)}& .note{font-size:var(--type-12)}& h2{font-size:var(--type-28)}& .kick{display:none}}'''
 write(d/'element.css',(base+css[folder]+responsive).replace('&',selector)+'\n')
 jwrite(d/'element.json',{'schema':'rhetis.design-library-element-source/1','contract':cid,'registrations':{},'tokenDefaults':{}})
 write(d/'description.md',f'The {folder} applies Confluence’s centred circular emphasis, soft inset panels and concise heavy hierarchy to the {cid.split("@")[0]} contract. Accent colour denotes one focal item, while quiet surfaces and thin rules preserve supporting context. Container steps reduce text and spacing for compact placements.\n')
 sample=REF/'samples/annual/elements'/folder/'fixtures'
 if folder in ['card','chart-bar']:sample=REF/'samples/confetti/elements'/folder/'fixtures'
 if folder in ['chart-donut','chart-line']:sample=REF/'samples/amethyst/elements'/folder/'fixtures'
 for f in sample.glob('*.html'):
  s=f.read_text();s=re.sub(r'data-el="(?:annual|confetti|amethyst)-','data-el="confluence-',s)
  # Full slot on fixture root, preserving all benchmark markup and all data.
  if folder not in ['card','callout','chart-area','chart-bar','chart-donut','chart-line']:
   s=re.sub(r'grid-column:[^;"\n]+;\s*grid-row:[^;"\n]+','grid-column:1 / span 12; grid-row:1 / span 6',s,count=1)
  write(d/'fixtures'/f.name,s)
