write(C/'elements/tag/fixtures/labels.html','<!-- min: 3x1 -->\n<div class="group" style="grid-column:1 / span 12; grid-row:1 / span 6"><span class="tag" data-el="confluence-tag">공동 연구 협약 체결</span><span class="tag" data-el="confluence-tag">2060년 신규 프로젝트</span></div>\n')
for folder in ['pricing','versus']:
 # Replace legacy list-only sample content with exact current list/tag contracts.
 for f in (C/'elements'/folder/'fixtures').glob('*.html'):
  s=f.read_text();s=re.sub(r'<ul class="list">', '<div class="list check" data-el="confluence-list">',s);s=s.replace('</ul>','</div>');s=re.sub(r'<li>(.*?)</li>',r'<div class="item"><p class="name">\1</p></div>',s);s=s.replace('<span class="tag">','<span class="tag" data-el="confluence-tag">');f.write_text(s)
 first=next((C/'elements'/folder/'fixtures').glob('*.html'));s=first.read_text();s=s.replace('2055','2060').replace('2056','2061').replace('베이직','공동 연구 기본형').replace('스탠다드','산학 협력 확장형').replace('엔터프라이즈','기관 통합 운영형').replace('29만','35만').replace('79만','95만');write(C/'elements'/folder/'fixtures/cooperation.html',s)
print('Built',len(folders),'elements',sum(len(list((d/'fixtures').glob('*.html'))) for d in (C/'elements').iterdir()),'fixtures')
